import { Prisma, PrismaClient } from "@prisma/client";
import {
  buildStandardPanelLayoutFromComponents,
  parseDualPanelLayoutJson,
  serializeDualPanelLayoutPayload,
  shouldAutoSyncPanelLayout,
} from "@/lib/panel-layout-template";

export type PanelSyncDb = PrismaClient | Prisma.TransactionClient;

/**
 * Menyinkronkan otomatis layout 2D panel (FR-EG-EP-006) dari daftar komponen PR aktif
 * jika proyek belum memiliki tata letak manual (`autoGenerated: false`).
 *
 * Jika user sudah menggeser / menyimpan layout manual, penataan posisi manual tidak ditimpa,
 * namun `componentId` yang berubah akibat simpan/re-import PR tetap direkonsiliasi agar hitungan panel list akurat.
 */
export async function syncAutoPanelLayoutForProject(
  db: PanelSyncDb,
  projectId: string,
  options?: { force?: boolean }
): Promise<boolean> {
  if (!projectId) return false;

  const project = await db.project.findUnique({
    where: { id: projectId },
    select: {
      id: true,
      panelLayoutJson: true,
    },
  });

  if (!project) return false;

  const components = await db.component.findMany({
    where: {
      projectId,
      statusImport: { not: "HILANG_DI_REVISI" },
    },
    orderBy: { urutan: "asc" },
    select: {
      id: true,
      partType: true,
      partName: true,
      qty: true,
      kelompok: true,
      supplier: true,
      catatanPr: true,
      statusImport: true,
    },
  });

  if (!options?.force && !shouldAutoSyncPanelLayout(project.panelLayoutJson)) {
    // Tetap rekonsiliasi componentId di layout manual jika ada komponen PR yang baru di-replace/re-import
    if (!project.panelLayoutJson || components.length === 0) {
      return false;
    }
    const reconciled = parseDualPanelLayoutJson(project.panelLayoutJson, components);
    const updatedPayload = serializeDualPanelLayoutPayload({
      ...reconciled,
      autoGenerated: false,
    });
    if (updatedPayload !== project.panelLayoutJson) {
      await db.project.update({
        where: { id: projectId },
        data: { panelLayoutJson: updatedPayload },
      });
      return true;
    }
    return false;
  }

  // Jika sebelumnya kosong sama sekali dan belum ada komponen aktif, tidak perlu menulis payload kosong
  if (components.length === 0 && !project.panelLayoutJson && !options?.force) {
    return false;
  }

  const autoLayout = buildStandardPanelLayoutFromComponents(components);
  const payload = serializeDualPanelLayoutPayload({
    ...autoLayout,
    autoGenerated: true,
    templateCode: "FR-EG-EP-006",
    lastSaved: new Date().toISOString(),
  });

  await db.project.update({
    where: { id: projectId },
    data: { panelLayoutJson: payload },
  });

  return true;
}
